python3 -c "
import json
with open('/app/resources/treasury_bulletin_2003_03.json') as f:
    data = json.load(f)

# Print keys at top level
def print_keys(obj, prefix=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            print(f'{prefix}{k}')
            if isinstance(v, dict) and len(v) < 20:
                print_keys(v, prefix + '  ')
            elif isinstance(v, list) and len(v) > 0:
                print(f'{prefix}  [{list(v[0].keys()) if isinstance(v[0], dict) else type(v[0]).__name__}]')

print_keys(data)
"

